    public Doctor_Frame() {
        initComponents();
        
        this.setLocationRelativeTo(null);
        
        
        ArrayList<String[]> doctorData = File_Control.readFile("doctorData.txt",true);
        boolean undoneData = false;
        
        for (String[] line : doctorData) {
            if (doctor.getUserID().equals(line[0])) {
                
                if (line[12].equals("-") || line[13].equals("-") || line[14].equals("-")) {
                    undoneData = true;
                }
                break;
            }
        }
        
        

        lblShowRole.setText("Welcome to Doctor Page!!!");

        lblDoctorName.setText(doctor.getUserName());
        
        if (undoneData) {
            openPage(Profile2Panel);
            
            loadProfile();
            
            JOptionPane.showMessageDialog(this, "Please complete your profile data before proceed to other functions!");
            lblProfile2Reminder.setText("Back button will be enabled once a value is entered.");
            
            cboAddLanguage.setVisible(false);
            btnCancelLanguage.setVisible(false);
            btnAddLanguage.setVisible(false);
            
            btnBack2Profile2.setEnabled(false);
        }
        else {
        
        openPage(WelcomePagePanel);
        
        cboSetting.setVisible(false);
        }


        
        
    }

