    public void generateMedicalReportOverview() {
        ArrayList<String[]> medicalData = File_Control.readFile("medicalReport.txt", true);
        ArrayList<String[]> patientData = File_Control.readFile("patientData.txt", true);
        ArrayList<String[]> childData = File_Control.readFile("childData.txt", true);
        ArrayList<String[]> doctorData = File_Control.readFile("doctorData.txt", true);
        String patientName = "";
        String patientAge = "";

        
        DefaultTableModel tableModel = new DefaultTableModel();
        DefaultComboBoxModel comboModel = new DefaultComboBoxModel();
        String[] tableTitle = {"MedicalReportID","Patient Name","Region","Gender","Age","Disease","Description","Consultant Doctor","Date","Consultance Fee","Payment Status","Blood Test"};
        tableModel.setColumnIdentifiers(tableTitle);
        
        for (String[] line : medicalData) {
            // to find patient name
            String patientID = line[1];
            if (patientID.startsWith("P")) {
                for (String[] list : patientData) {
                    if (list[0].equals(patientID)) {
                        patientName = list[1];
                        patientAge = list[3];
                    }
                }
            }
            else {
                for (String[] list : childData) {
                    if (list[0].equals(patientID)) {
                        patientName = list[2];
                        patientAge = childAgeConverter(list[6]);
                    }
                }
            }
            
            if (line[10].equals("1")) {
                line[10] = "Unpaid";
            }
            else if (line[10].equals("0")) {
                line[10] = "Paid";
            }
            
            for (String[] each : doctorData) {
                if (each[0].equals(line[7])) {
                    line[7] = each[1];
                }
            }
            
            line[1] = patientName;
            line[4] = patientAge;
            tableModel.addRow(line);
            
        }
        tblMedicalReportOverview.setModel(tableModel);
        cboDetailsClass.setModel(comboModel);
        tblMedicalReportOverview.setEnabled(false);
    }
    
        
