    private void cboSettingActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_cboSettingActionPerformed
               
        switch (cboSetting.getSelectedIndex()) {
            case 0 -> 
            {               
                openPage(ProfilePagePanel);
                
                loadProfile();
                
                cboSetting.setVisible(false);
            }
            case 1 ->
            {
                openPage(PasswordPanel);
                
                lblPasswordReminder.setText(""); 
                
                cboSetting.setVisible(false);
            }
            case 2 ->
            {                
                openPage(ChangeSafetyQuestionPanel);
                
                ModifySafetyQuestionPanel.setVisible(true);
                
                loadSafetyQuestionComboBox();
                
                lblSafetyReminder.setText("Viewing...");
                
                cboSetting.setVisible(false);
            }
        }
        
        
    }//GEN-LAST:event_cboSettingActionPerformed

    public final void loadProfile() {
        
        showSafetyDataStatus();
        txtDoctorID.setText(doctor.getUserID());
        txtName.setText(doctor.getUserName());
        txtEmail.setText(doctor.getEmail());
        txtSpecialist.setText(doctor.getSpecialist());
        txtRegion.setText(doctor.getRegion());
        txtIcNumber.setText(doctor.getIcNumber());
        txtRoom.setText(doctor.getRoom());
        txtNationality.setText(doctor.getNationality());
        txtContactNumber.setText(doctor.getContactNumber());
        txtGender.setText(doctor.getGender());
        lblReminder.setText("Viewing...");

        // for profile 2
        txtAge.setText(Integer.toString(doctor.getAge()));
        txtQualification.setText(doctor.getQualification());
        if (doctor.getExperience() == 0) {
            txtExperiences.setText("-");
        }
        else {
            txtExperiences.setText(Integer.toString(doctor.getExperience()));
        }
        

        String[] languages = doctor.getSpokenLanguage().split(",");

        DefaultListModel<String> sl = new DefaultListModel();
        lstShowLanguage.setModel(sl);
                        
        for (String language : languages) {
            sl.addElement(language);
        }


        if (doctor.getAccountStatus() == 1) {
            txtAccStatus.setText("Active");
        }
        else {
            txtAccStatus.setText("Deleted");
        }


        String[] workingDays = doctor.getWorkingDay().split("/");

        ArrayList<String> newDay = new ArrayList<>();


        for (String day : workingDays) {
            if (!(day.isEmpty())) {
                switch (day) {
                case "1" -> newDay.add("Monday");
                case "2" -> newDay.add("Tuesday");
                case "3" -> newDay.add("Wednesday");
                case "4" -> newDay.add("Thursday");
                case "5" -> newDay.add("Friday");
            }
            }
            else;
        }

        // Convert the arrayList into String
        String shiftDays = String.join(",", newDay);
        txtShiftDay.setText(shiftDays);

        DisenableText();
    }
    public void showSafetyDataStatus() {
        if (doctor.getSafetyQuestionID1().equals("-") || doctor.getSafetyQuestionID2().equals("-")) {
            lblSQTips.setVisible(true);
            lblSQTips2.setVisible(true);
        }
        else {
            lblSQTips.setVisible(false);
            lblSQTips2.setVisible(false);
        }
    }
    public void loadSafetyQuestionComboBox() {
        ArrayList<String[]> safetyData = File_Control.readFile("securityQuestion.txt", true);
        
        String fullQuestion1 = "";
        String fullQuestion2 = "";
        
        
        cboSafetyQuestion1.setEnabled(false);
        cboSafetyQuestion2.setEnabled(false);
        txtAnswerSQ1.setEnabled(false);
        txtAnswerQS2.setEnabled(false);
        
        

        
        DefaultComboBoxModel comboModelA = new DefaultComboBoxModel();
        DefaultComboBoxModel comboModelB = new DefaultComboBoxModel();
        
        for (String[] list : safetyData) {
            comboModelA.addElement(list[1]);
            comboModelB.addElement(list[1]);
        }
        
        cboSafetyQuestion1.setModel(comboModelA);
        
        cboSafetyQuestion2.setModel(comboModelB);
        
        if (!doctor.getSafetyQuestionID1().equals("-") && !doctor.getSafetyQuestionID2().equals("-")) {
            for (String[] each : safetyData) {
                if (each[0].equals(doctor.getSafetyQuestionID1())) {
                    fullQuestion1 = each[1];
                }
                else if (each[0].equals(doctor.getSafetyQuestionID2())) {
                    fullQuestion2 = each[1];
                }
            }
            cboSafetyQuestion1.setSelectedItem(fullQuestion1);
            cboSafetyQuestion2.setSelectedItem(fullQuestion2);
            
            txtAnswerSQ1.setText(doctor.getSafetyAnswer1());
            txtAnswerQS2.setText(doctor.getSafetyAnswer2());
            
            btnEditSafetyQuestion.setText("Edit");
        }
        else {
            btnEditSafetyQuestion.setText("Initialize");
        }
    }
