    private void btnSaveProfileActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnSaveProfileActionPerformed
        if (txtContactNumber.isEnabled()) {
        
        String newName = txtName.getText().trim();
        String newEmail = txtEmail.getText().trim();
        String newRegion = txtRegion.getText().trim();
        String newContactNumber = txtContactNumber.getText().trim();
        String newNationality = txtNationality.getText().trim();

        boolean nameDetector = false;
        
        if (newName.isEmpty() || newEmail.isEmpty() || newRegion.isEmpty() || newContactNumber.isEmpty()
                || newNationality.isEmpty()) 
        {
            lblReminder.setText("Please do not key in empty data.");
        }
        else {
            if (!Validation.string(newName)) {
                lblReminder.setText("Name can only contain letters.");
            }
            else if (!Validation.email(newEmail)) {
                lblReminder.setText("Please enter a valid email address (e.g., abc@gmail.com).");
            }
            else if (!Validation.string(newRegion)) {
                lblReminder.setText("Region can only contain letters.");
            }
            else if (!Validation.contactNumber(newContactNumber)) {
                lblReminder.setText("Contact number must contain 10 to 11 digits.");
            }
            else if (!Validation.string(newNationality)) {
                lblReminder.setText("Nationality can only contain letters.");
            }
            else {
                
                if (!doctor.getUserName().equals(newName)) {
                    nameDetector = true;
                }
                
            doctor.setUserName(newName);
            doctor.setEmail(newEmail);
            doctor.setRegion(newRegion);
            doctor.setContactNumber(newContactNumber);
            doctor.setNationality(newNationality);
            
            DisenableText();
            
            doctor.updateProfile("page1");
            
            
            if (nameDetector) {
                Main.setCurrentUserName(doctor.getUserName());
                
                lblDoctorName.setText(doctor.getUserName());
                
                doctor.updateLogInName();
            }
            
            lblReminder.setText("Data Update Successfully.");
        }
        }
        }
        else {
            lblReminder.setText("Please edit before save.");
        }
    }//GEN-LAST:event_btnSaveProfileActionPerformed

