    private void btnChangePasswordActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnChangePasswordActionPerformed
           String oldPassword = txtOldPassword.getText();
           String newPassword1 = txtNewPassword1.getText();
           String newPassword2 = txtNewPassword2.getText();
           
           boolean passwordDetector = false;
           if (!(oldPassword.isEmpty()) || !(newPassword1.isEmpty()) || !(newPassword2.isEmpty())) {
               
                   if (doctor.getUserPassword().equals(oldPassword)) {
                       if (!newPassword1.equals(doctor.getUserPassword())) {
                   if (Validation.password(newPassword1)) {
                   if (newPassword1.equals(newPassword2)) {
                       doctor.setUserPassword(newPassword1);
                       doctor.updatePassword();
                       
                       passwordDetector = true;
                   }
                   else {
                       txtNewPassword1.setText("");
                       txtNewPassword2.setText("");
                       
                       lblPasswordReminder.setText("Please ensure both new password are consistence.");
                   }
                   }
                   else {
                       lblPasswordReminder.setText("Please follow the password format above.");
                   }
                   }
                       else {
                           lblPasswordReminder.setText("Please do not reuse your old password as the new one.");
                       }
                   }
                   else {
                   txtOldPassword.setText("");
                   txtNewPassword1.setText("");
                   txtNewPassword2.setText("");
                   
                   lblPasswordReminder.setText("Please ensure the old password is true.");
             
           
           }
           
           if (passwordDetector) {                   
                   txtOldPassword.setText("");
                   txtNewPassword1.setText("");
                   txtNewPassword2.setText("");
                   
                   
                   lblPasswordReminder.setText("Password Update Successfully!");
               }
           }
           
               else {
                   txtOldPassword.setText("");
                   txtNewPassword1.setText("");
                   txtNewPassword2.setText("");
                   
                   lblPasswordReminder.setText("Please fill up all the text fields.");
               }
           
           
    }//GEN-LAST:event_btnChangePasswordActionPerformed

