    private void btnSaveProfile2ActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnSaveProfile2ActionPerformed
    String newAge = txtAge.getText();
    String newQualification = txtQualification.getText().strip();
    String newExperience = txtExperiences.getText().strip();
    
    ListModel<String> listModel = lstShowLanguage.getModel();
    
    if (txtAge.isEnabled() && txtQualification.isEnabled() && txtExperiences.isEnabled()) {
        
    
    String newLanguage = "";
    
    if (newAge.isEmpty() || newQualification.isEmpty() || newExperience.isEmpty()) {
        lblProfile2Reminder.setText("Please do not leave any fields empty");
    }
    else if (listModel.toString().strip().equals("[-]") && !cboAddLanguage.isVisible()) {
        lblProfile2Reminder.setText("Please select at least one spoken language.");
    }
    else {
        if (!Validation.age(newAge)) {
            lblProfile2Reminder.setText("Age must be a number between 1 and 99.");
        }
        else if (!Validation.string(newQualification)) {
            lblProfile2Reminder.setText("Qualification can only contain letters.");
        }
        else if (!Validation.integer(newExperience)) {
            lblProfile2Reminder.setText("Experience must contain numbers only.");
        }
        else {
            doctor.setAge(Integer.parseInt(txtAge.getText()));
            doctor.setQualification(txtQualification.getText());
            doctor.setExperience(Integer.parseInt(txtExperiences.getText()));
    
    if (cboAddLanguage.isVisible() && !(cboAddLanguage.getSelectedItem() == null)) {
                String[] languages = doctor.getSpokenLanguage().split(",");
                
                ArrayList<String> newList = new ArrayList<>(Arrays.asList(languages));
                newList.add(cboAddLanguage.getSelectedItem().toString());
                
                if (newList.get(0).equals("-")) {
                    newList.remove(0);
                }
                
                newLanguage = String.join(",", newList);
                
                doctor.setSpokenLanguage(newLanguage);
                doctor.updateSpokenLanguage();
}
        
    
            doctor.updateProfile("page2");
            
    btnAddLanguage.setVisible(false);
    
    lblProfile2Reminder.setText("Data Update Successfully.");
    
    txtAge.setEnabled(false);
    txtQualification.setEnabled(false);
    txtExperiences.setEnabled(false);
    
    cboAddLanguage.setVisible(false);
    btnCancelLanguage.setVisible(false);
    
    btnBack2Profile2.setEnabled(true);
    
    loadProfile();
    }
    }
    }
    
    
    else {
        lblProfile2Reminder.setText("Please edit first.");
    }
    
    
    }//GEN-LAST:event_btnSaveProfile2ActionPerformed

