    private void cboPrescriptionSearchActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_cboPrescriptionSearchActionPerformed
        ArrayList<String[]> dataList = File_Control.readFile("patientData.txt", true);
        ArrayList<String[]> childList = File_Control.readFile("childData.txt",true);
        
        if (cboPrescriptionSearch.getSelectedItem().toString().startsWith("P")) {
        for (String[] list : dataList) {
            String patientID = list[0];
            String patientName = list[1];
            String icNumber = list[2];
            String gender = list[4];
            String region = list[8];
            
            if (cboPrescriptionSearch.getSelectedItem().equals(patientID)) {
                txtPatientNameDisplay.setText(patientName);
                txtPatientRegionDisplay.setText(region);
                cboIcNoDisplay.setText(icNumber);
                
                if (gender.equals("Male")) {
                    lblMaleIcon.setVisible(true);
                    lblFemaleIcon.setVisible(false);
                }
                else if (gender.equals("Female")) {
                    lblMaleIcon.setVisible(false);
                    lblFemaleIcon.setVisible(true);
                }
            }
        }
        }
        else {
            for (String[] list : childList) {
            String patientID = list[0];
            String patientName = list[2];
            String icNumber = list[3];
            String gender = list[4];
            String region = list[5];
            
            if (cboPrescriptionSearch.getSelectedItem().equals(patientID)) {
                txtPatientNameDisplay.setText(patientName);
                txtPatientRegionDisplay.setText(region);
                cboIcNoDisplay.setText(icNumber);
                
                if (gender.equals("Male")) {
                    lblMaleIcon.setVisible(true);
                    lblFemaleIcon.setVisible(false);
                }
                else if (gender.equals("Female")) {
                    lblMaleIcon.setVisible(false);
                    lblFemaleIcon.setVisible(true);
                }
            }
                }

    }
    }//GEN-LAST:event_cboPrescriptionSearchActionPerformed

    private void jButton2ActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jButton2ActionPerformed
        if (!txtPatientNameDisplay.getText().strip().isEmpty()) {
        ArrayList<String[]> patientData = File_Control.readFile("patientData.txt",true);
        ArrayList<String[]> childData = File_Control.readFile("childData.txt",true);
        String patientID = cboPrescriptionSearch.getSelectedItem().toString();
        
        findPatientPanel.setVisible(false);
        DiseaseDescriptionPanel.setVisible(true);
        AddBloodTestReportPanel.setVisible(false);
        
        String patientName = "";
        String patientGender = "";
        String patientAge = "";
        String patientRegion = "";
        
        if (patientID.startsWith("P")) {
            lblAge.setText("Age");
        for (String[] list : patientData) {
            if (patientID.equals(list[0])) 
            {
                patientName = list[1];
                patientGender = list[4];
                patientAge = list[3];
                patientRegion = list[8];
                break;
                
            }
        }
        }
        else {
            lblAge.setText("Age (Year, Month):");
             for (String[] list : childData) {
            if (patientID.equals(list[0])) 
            {
                patientName = list[2];
                patientGender = list[4];
                patientAge = list[6];
                patientRegion = list[5];
                break;
                
            }
        }
        }
        
        LocalDate date = LocalDate.now();
        
        String[] diseases = {};
        switch (doctor.getSpecialist()) {
            case "Cardiology" -> {
                diseases = new String[]{"Angina", "Arrhythmia", "Coronary Artery Disease", "Heart Failure", "Hypertension", "Myocardial Infarction"};
            }
            case "Neurology" -> {
                diseases = new String[]{"Alzheimer’s Disease", "Epilepsy", "Migraine", "Multiple Sclerosis", "Parkinson’s Disease", "Stroke"};
            }
            case "Ophthalmology" -> {
                diseases = new String[]{"Cataract", "Conjunctivitis", "Diabetic Retinopathy", "Dry Eye Syndrome", "Glaucoma", "Macular Degeneration"};
            }
            case "Pediatrics" -> {
                diseases = new String[]{"Asthma", "Bronchitis", "Chickenpox", "Measles", "Mumps", "Pneumonia"};
            }
        }
                
        DefaultComboBoxModel<String> comboModel = new DefaultComboBoxModel<>();

        for (String list : diseases) {
            comboModel.addElement(list);
        }

        cboDiseaseType.setModel(comboModel);
        

        
        txtPatientID.setText(patientID);
        txtPatientName.setText(patientName);
        txtPatientGender.setText(patientGender);
        lblConsultanceDate.setText(date.toString());
        txtPatientAge.setText(patientAge);
        txtPatientRegion.setText(patientRegion);
        
        taDescription.setLineWrap(true);   // allow type wrapping
        taDescription.setWrapStyleWord(true); 
        txtConsultanceFee.setText("");
        taDescription.setText("");
        
        txtPatientID.setEnabled(false);
        txtPatientName.setEnabled(false);
        txtPatientGender.setEnabled(false);
        txtPatientAge.setEnabled(false);
        txtPatientRegion.setEnabled(false);
        }
        
        
    }//GEN-LAST:event_jButton2ActionPerformed

