    private void btnConfirmPrescribeMedicationActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnConfirmPrescribeMedicationActionPerformed
        ArrayList<String[]> inventoryData = File_Control.readFile("inventoryData.txt",true);
        ListModel<String> model = lstMedicines.getModel();
        String medicineDetails = "";
        double fees = 0.0;
        
        
        if (model.getSize() != 0) {
            int counter = 0;
            for (int i = 0 ; i < model.getSize() ; i++) {
                if (counter == 0) {
                    medicineDetails = model.getElementAt(i);
                    counter ++;
                }
                else {
                    medicineDetails = medicineDetails  + "/" + model.getElementAt(i);
                    counter ++;
                }
            }          
            
            String newID = Utility_Methods.autoGenerateID("prescriptionData.txt", "PR");
        
            
            // calculating fees 
            for (int j = 0 ; j < model.getSize() ; j++) {
                String item = model.getElementAt(j);
                String[] each = item.split(",");
                String itemID = each[0];
                int amount = Integer.parseInt(each[2]);
                
                for (String[] line : inventoryData) {
                    if (itemID.equals(line[0])) {
                        double unitPrice = Double.parseDouble(line[4]);
                        double price = amount * unitPrice;
                        fees += price;
                    }
                } 
            }


            String formatedFees = String.format("%.2f", fees);
            LocalDate date = LocalDate.now();
            String currentDate = date.toString();
            String MRID = cboFindMedicalReportID.getSelectedItem().toString();

            
            Prescription prescription = new Prescription(newID, MRID, medicineDetails, currentDate,"-", "-", formatedFees , "1");
            prescription.addPrescription();



            checkBoxPrescribeMedication.setSelected(false);
            btnConfirmPrescribeMedication.setEnabled(false);
            JOptionPane.showMessageDialog(this, "Medication prescribed successfully.");

            lblDoctorName.setText(doctor.getUserName());
            openPage(WelcomePagePanel);
        }
        else {
            JOptionPane.showMessageDialog(this, "Please add at least one medicine to save", "warning", JOptionPane.WARNING_MESSAGE);
        }
        
        
        
    }//GEN-LAST:event_btnConfirmPrescribeMedicationActionPerformed

