    public void GenerateMedicalReport(boolean withReport) {
        String newID = Utility_Methods.autoGenerateID("medicalReport.txt", "MR");
        String formatedConsultanceFee = "";
        String bloodTestResult = "-";
        boolean trueStatus = false;
        
        String consultanceFee = txtConsultanceFee.getText();
        
        boolean consultanceFeeValid = Validation.price(consultanceFee);
        
        
        if (consultanceFeeValid == false) {
            JOptionPane.showMessageDialog(this, "Consultance fee is required and must contain numbers only!", "warning", JOptionPane.WARNING_MESSAGE);
            txtConsultanceFee.setText("");
        }
        
        else {
            formatedConsultanceFee = Utility_Methods.definePriceFormat(consultanceFee);
        }
        
        String patientID = txtPatientID.getText();
        String date = lblConsultanceDate.getText();
        String disease = cboDiseaseType.getSelectedItem().toString();
        String gender = txtPatientGender.getText();
        String age = txtPatientAge.getText();
        String region = txtPatientRegion.getText();
        
        String description = "";
        
        if (taDescription.getText().strip().isEmpty()) {
            description = "-";
        }
        else {
            description = taDescription.getText();
        }
        if (consultanceFeeValid) {
            if (withReport == true) {
                String glucose = txtGlucose.getText();
                String cholesterol = txtCholesterol.getText();
                String hemoglobin = txtHemoglobin.getText();
                String glucoseLevel = cboGlucose.getSelectedItem().toString();
                String cholesterolLevel = cboCholesterol.getSelectedItem().toString();
                String hemoglobinLevel = cboHemoglobin.getSelectedItem().toString();
                
                String glucoseFormal = CheckBloodTestFormat(glucose);
                String cholesterolFormal = CheckBloodTestFormat(cholesterol);
                String hemoglobinFormal = CheckBloodTestFormat(hemoglobin);
                
                if (!glucoseFormal.isEmpty() && !cholesterolFormal.isEmpty() && !hemoglobinFormal.isEmpty()) {
                    System.out.println(glucoseFormal);
                    bloodTestResult = "Glucose: " + glucoseFormal + " mmol/L (" + glucoseLevel + "),Cholesterol: " + cholesterolFormal + " mg/dL (" +
                            cholesterolLevel + "),Hemoglobin: " + hemoglobinFormal + " g/dL (" + hemoglobinLevel + ")";
                    trueStatus = true;
                    }
                else {
                    JOptionPane.showMessageDialog(this, "Please enter a valid result (numbers or decimals only)!", "warning", JOptionPane.WARNING_MESSAGE);
                }
                    }
                else {
                trueStatus = true;
            }
            if (trueStatus) {
                Consultance consultance = new Consultance(newID, patientID, region, gender, age, disease, description, doctor.getUserID(), date, formatedConsultanceFee, "1", bloodTestResult);
//                String newRecord = String.join(";", newID, patientID, region, gender, age, disease, description, doctor.getUserID(), date, formatedConsultanceFee, "1", bloodTestResult, "1");
//                File_Control.addData("medicalReport.txt",newRecord);
                consultance.saveMedicalReport();
                JOptionPane.showMessageDialog(this, "Consultance data with blood report successfully saved!");
                txtConsultanceFee.setText("");
                taDescription.setText("");
                txtGlucose.setText("");
                txtCholesterol.setText("");
                txtHemoglobin.setText("");
                
                if (withReport == true) {
                    ShowMedicalSlip(true);
                }
                else {
                    ShowMedicalSlip(false);
                }
                        
                findPatientPanel.setVisible(false);
                DiseaseDescriptionPanel.setVisible(false);
                AddBloodTestReportPanel.setVisible(false);
                MedicalSlipPanel.setVisible(true);
            }
        }
    }
    
    public String CheckBloodTestFormat(String inputString) {
        String number = inputString;
        try {
            double test = Double.parseDouble(number);
            String formatNumber = String.format("%.2f", test);
            return formatNumber;
        }
        catch (NumberFormatException e) {
            return "";
        }
    }
