    private void btnAddMedicineActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnAddMedicineActionPerformed
        
        String mrID = "";
        int intQuantity = 0;
        int max = 0;
        boolean numberVerify = false;
        
        ArrayList<String[]> dataList = File_Control.readFile("inventoryData.txt",true);
        
        
        String quantity = txtQuantity.getText().strip();
        String medicine = cboMedicineSelect.getSelectedItem().toString().strip();
        String frequency = cboFrequency.getSelectedItem().toString().strip();
        String timing = cboTiming.getSelectedItem().toString().strip();
        
        // ensure only the quantity below stock is selected
        
        for (String[] list : dataList) {
            if (medicine.equals(list[1])) {
            max = Integer.parseInt(list[6]);
            break;
            }
        }       
        
        
        try {
            intQuantity = Integer.parseInt(quantity);
            numberVerify = true;
        }
        catch (NumberFormatException e) {
            
        }
        
        // to remove the selected selection
        
        DefaultComboBoxModel<String> comboModel = new DefaultComboBoxModel<>();
        // get current available selection
        ComboBoxModel<String> sampleModel = cboMedicineSelect.getModel();
        // to create an arrayList to store selection for remove the same data
        ArrayList<String> medicineSelection = new ArrayList<>();
        
        if (sampleModel.getSize() != 0) {
            for (int x = 0; x < sampleModel.getSize() ; x++) {
                medicineSelection.add(sampleModel.getElementAt(x));
            }
            
            // remove the selected item
            medicineSelection.remove(medicine);

            // put new data into comboModel
            for (String newMedicine : medicineSelection) {
                comboModel.addElement(newMedicine);
            }
            
            cboMedicineSelect.setModel(comboModel);
        }

        
        ListModel<String> model = lstMedicines.getModel();

        DefaultListModel<String> listModel = new DefaultListModel();
        
        if (numberVerify && Integer.parseInt(quantity) <= max && Integer.parseInt(quantity) > 0) {
            for (String[] list : dataList) {
                if (medicine.equals(list[1])) {
                    mrID = list[0];
                    break;
                }
                }
            
            if(model.getSize() > 0) {
                for (int i = 0; i < model.getSize() ; i++) {
                    listModel.addElement(model.getElementAt(i));
                }
            }
            
            listModel.addElement(String.join(",", mrID, medicine, Integer.toString(intQuantity), frequency, timing));
            
            lstMedicines.setModel(listModel);
            
            txtQuantity.setText("");         
            
            
            
        }
        else {
            JOptionPane.showMessageDialog(this,"Quantity is required, must be numeric, and cannot exceed available stock.", "warning", JOptionPane.WARNING_MESSAGE);
            
            txtQuantity.setText("");
        }
        

        
        
    }//GEN-LAST:event_btnAddMedicineActionPerformed

