    private void cboFindMedicalReportIDActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_cboFindMedicalReportIDActionPerformed
        String mrID = cboFindMedicalReportID.getSelectedItem().toString().strip();

        ArrayList<String[]> mrData = File_Control.readFile("medicalReport.txt",true);
        ArrayList<String[]> patientData = File_Control.readFile("patientData.txt",true);
        ArrayList<String[]> childDataList = File_Control.readFile("childData.txt", true);

        for (String[] list : mrData) {
            if (mrID.equals(list[0])) {
                String patientID = list[1];
                String patientName = "";
                String disease = list[5];
                String date = list[8];

                if (patientID.startsWith("P")) {
                    for (String[] line : patientData) {
                        if (line[0].equals(patientID)) {
                            patientName = line[1];
                            break;
                        }
                    }
                }
                else {
                    for (String[] line : childDataList) {
                        if (line[0].equals(patientID)) {
                            patientName = line[2];
                            break;
                        }
                    }
                }

                txtPatientNameMR.setText(patientName);
                txtDiseaseMR.setText(disease);
                txtConsultanceDateMR.setText(date);
            }
        }
    }//GEN-LAST:event_cboFindMedicalReportIDActionPerformed

