    public void initializeAppointmentPending() {
        
        // to let the index start from zero
        curIndex = 0;
        
        // to get the doctor's appointment list and assign into this global variable
        Appointment appointment = new Appointment();
        appointment.setDoctorID(doctor.getUserID());
        myTempList = appointment.initilizePendingAppointment();
        // get current date

        // only proceed into that page if there have available upcoming appointment waiting for approve
        if (myTempList.size() >= 1) {
        ViewPendingAppointment(curIndex);
        CheckAppointmentPanel.setVisible(false);
        ExistingAppointmentPanel.setVisible(false);
        PendingAppointmentPanel.setVisible(true);
        }
        else {
            JOptionPane.showMessageDialog(this, "There are no requested appointments at the moment.");
            CheckAppointmentPanel.setVisible(true);
            ExistingAppointmentPanel.setVisible(false);
            PendingAppointmentPanel.setVisible(false);
        }
        txtStatus.setEnabled(false);
    }
