    public void showPatientCard(boolean givenData) {
        if (givenData) {
        ArrayList<String[]> patientData = File_Control.readFile("patientData.txt",true);
        ArrayList<String[]> childData = File_Control.readFile("childData.txt", true);
        
        String patientID = patientRecordSelectedID();
        String name = "";
        String age = "";
        String blood = "";
        String region = "";
        
        
        if (patientID.startsWith("P")) {
            for (String[] data : patientData) {
                if (patientID.equals(data[0])) {
                  name = data[1];
                  age = data[3];
                  blood = data[9];
                  region = data[8];
                  break;
                }
            }
        }
        else {
            for (String[] data : childData) {
                if (patientID.equals(data[0])) {
                  name = data[2];
                  age = data[6];
                  blood = data[7];
                  region = data[5];
                  break;
                }
            }
        }
        
        if (patientID.startsWith("C")) {
            //convert child into format which show years and months
            age = childAgeConverter(age);
        }
        
        lblPatientNameDisplay.setText(name);
        lblPatientAgeDisplay.setText(age);
        lblPatientBloodDisplay.setText(blood);
        lblPatientRegionDisplay.setText(region);
        }
        else {
            lblPatientNameDisplay.setText("Name");
            lblPatientAgeDisplay.setText("-");
            lblPatientBloodDisplay.setText("-");
            lblPatientRegionDisplay.setText("-");

        }
    }
    
    // to convert child age from x,y into x years y months when display
    String childAgeConverter(String age) {
        String[] childAge = age.split(",");
            
        //reassign age for child
        String newAge = childAge[0] + " Years " + childAge[1] + " Months";
        return newAge;
    }
