    public void refreshModifyAdditionalPage() {
        ArrayList<String[]> patientData = File_Control.readFile("patientData.txt", true);
        ArrayList<String[]> childData = File_Control.readFile("childData.txt", true);
        
        String allergies = "";
        String lifeStyle = "";
        
        String patientID = patientRecordSelectedID();
        
        if (patientID.startsWith("P")) {
        for (String[] line : patientData) {
            if (line[0].equals(patientID)) {
                allergies = line[10];
                lifeStyle = line[11];
            }
        }
        }
        else {
            for (String[] line : childData) {
               if (line[0].equals(patientID)) {
                   allergies = line[8];
                   lifeStyle = line[9];
               }
        }
        }
        
        //model for display allergies
        DefaultListModel<String> listModel = new DefaultListModel();
        
        //model for select allergies
        DefaultComboBoxModel<String> comboBoxModel = new DefaultComboBoxModel();
        
        // allergies available
        ArrayList<String> foodAllergies;
        foodAllergies = new ArrayList<>(Arrays.asList(
                "Peanuts", "Tree Nuts", "Milk", "Eggs", "Fish",
                "Shellfish", "Soy", "Wheat", "Sesame", "Mustard",
                "Corn", "Beef", "Chicken", "Pork", "Chocolate",
                "Strawberries", "Kiwi", "Bananas"
        ));
        
        //create a copy for removing element
        ArrayList<String> temp = new ArrayList<>(foodAllergies);
        
        if (allergies.equals("-")) {
            for (String eachAllergies : foodAllergies) {
            comboBoxModel.addElement(eachAllergies);
            }
            cboAllerySelection.setModel(comboBoxModel);
            
            listModel.addElement("empty");
            lblExistingAllergies.setModel(listModel);
        }
        else {
            String[] allergiesList = allergies.split(",");
            
            // add allergies to display on list
            for (String list : allergiesList) {
                listModel.addElement(list);
            }
            
            // remove data from allergies selection list if the data redundent
            for (String allergiesNow : allergiesList) {
                for (String eachFood : foodAllergies) {
                    if (allergiesNow.contains(eachFood)) {
                        temp.remove(eachFood);
                    }
                }
            }
            
            //add the new selection list
            for (String Selection : temp) {
                comboBoxModel.addElement(Selection);
            }
            
            // put new food allergies selection into combobox
            cboAllerySelection.setModel(comboBoxModel);
            
            // display current allergies
            lblExistingAllergies.setModel(listModel);
        }
        
        String[] lifeStyleList = lifeStyle.split(",");
        
        String smooking = lifeStyleList[0];
        String drinking = lifeStyleList[1];
        String exercise = lifeStyleList[2];
        String eating = lifeStyleList[3];
        
        lblDisplaySmoking.setText(smooking);
        lblDisplayDrinking.setText(drinking);
        lblDisplayExercise.setText(exercise);
        lblDisplayEating.setText(eating);
        
        DefaultComboBoxModel newComboModel = new DefaultComboBoxModel();
        newComboModel.addElement("Smooking");
        newComboModel.addElement("Drinking");
        newComboModel.addElement("Exercise");
        newComboModel.addElement("Eating");
        cboLifeStyleSelect.setModel(newComboModel);
        
        DefaultComboBoxModel emptyComboModel = new DefaultComboBoxModel();
        cboLifeStyleStatusSelect.setModel(emptyComboModel);
        
        
        btnAddAllergy.setEnabled(false);
        btnUpdateLifeStyle.setEnabled(false);
        lblDisplaySmoking.setEnabled(false);
        lblDisplayDrinking.setEnabled(false);
        lblDisplayExercise.setEnabled(false);
        lblDisplayEating.setEnabled(false);
        checkboxAllergies.setSelected(false);
       
        
    }
    private void jButton8ActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jButton8ActionPerformed
        ArrayList<String[]> medicalReportData = File_Control.readFile("medicalReport.txt",true);
        
        String patientID = patientRecordSelectedID();
        
        String[] tableTitle = {"Medical Report ID","Date","Disease","Description"};
        
        DefaultTableModel tableModel = new DefaultTableModel();
        tableModel.setColumnIdentifiers(tableTitle);
        
        DefaultTableModel tableModelBloodTest = new DefaultTableModel();
        String[] bloodTestTableTitle = {"Date","Glucose","Cholesterol","Hemoglobin"};
        tableModelBloodTest.setColumnIdentifiers(bloodTestTableTitle);
        
        for (String[] line : medicalReportData) {
            // to load the medical reports
            if (patientID.equals(line[1])) {
                tableModel.addRow(new String[]{line[0],line[8],line[5],line[6]});
                
                // to load the blood test if have
                if (!line[11].equals("-")) {
                    String[] bloodTestResult = line[11].split(",");
                    tableModelBloodTest.addRow(new String[]{line[8],bloodTestResult[0].substring(bloodTestResult[0].indexOf(":") + 2),
                        bloodTestResult[1].substring(bloodTestResult[1].indexOf(":") + 2),bloodTestResult[2].substring(bloodTestResult[2].indexOf(":") + 2)});
                }
            }
        }
        
        tblPatientDisease.setModel(tableModel);
        tblPatientBloodTest.setModel(tableModelBloodTest);
        
        
        IdentifyPatientRecordPanel.setVisible(false);
        ShowPatientCommonRecordPage.setVisible(false);
        ShowPatientMedicalReportPanel.setVisible(true);
        ModifyAdditionalRecordPanel.setVisible(false);
    }//GEN-LAST:event_jButton8ActionPerformed

