    public void ShowMedicalSlip(boolean withReport) {
        ArrayList<String[]> patientData = File_Control.readFile("patientData.txt", true);
        ArrayList<String[]> childData = File_Control.readFile("childData.txt", true);
        ArrayList<String[]> medicalReport = File_Control.readFile("medicalReport.txt", true);
        
        String reportID = "";
        String patientName = "";
        String patientAge = "";
        String patientGender = "";
        String patientRegion = "";
        String consultanceFee = "";
        String paymentStatus = "";
        String Disease = "";
        String description = "";
        String date = "";
        
        String[] medicalData = null;
        // create arrayList to store blood test
        ArrayList<String> bloodTestResult = new ArrayList<>();
        
        String patientID = txtPatientID.getText();
        
        // get all needed data to display
        if (patientID.startsWith("P")) {
            for (String[] line : patientData) {
                if (patientID.equals(line[0])) {
                    patientName = line[1];
                    patientAge = line[3];
                    patientGender = line[4];
                    patientRegion = line[8];
                }
            }
        }
        else {
            for (String[] line : childData) {
                patientName = line[2];
                patientAge = line[6];
                patientAge = childAgeConverter(patientAge);
                patientGender = line[4];
                patientRegion = line[5];
            }
        }
        
        for (String[] list : medicalReport) {
            if (patientID.equals(list[1]) && doctor.getUserID().equals(list[7])) {
                medicalData = list;
            }
        }
        
        //use the latest data to assign
        
       reportID = medicalData[0];
       Disease = medicalData[5];
       consultanceFee = "$ " + medicalData[9];
       description = medicalData[6];
       paymentStatus = medicalData[10];
       date = medicalData[8];
       
       if (withReport == true) {
                    bloodTestResult.addAll(Arrays.asList(medicalData[11].split(",")));
       }
       
       
       if (paymentStatus.equals("1")) {
           paymentStatus = "Unpaid";
       }
       else {
           paymentStatus = "Paid";
       }
       // enabling wrapping in text area
       taMRDescription.setLineWrap(true);
       taMRDescription.setWrapStyleWord(true);
       
       // assign data into slip

       lblMRID.setText(reportID);
       lblMRDate.setText(date);
       lblMRSpecialize.setText(doctor.getSpecialist());
       lblMRDoctorID.setText(doctor.getUserID());
       lblMRDoctorName.setText(doctor.getUserName());
       lblMRPatientID.setText(patientID);
       lblMRPatientName.setText(patientName);
       lblMRPatientAge.setText(patientAge);
       lblMRPatientGender.setText(patientGender);
       lblMRPatientRegion.setText(patientRegion);
       lblMRDisease.setText(Disease);
       taMRDescription.setText(description);
       taMRDescription.setEnabled(false);
       lblMRConsultanceFee.setText(consultanceFee);
       lblMRPaymentStatus.setText(paymentStatus);
       
       DefaultComboBoxModel<String> comboModel = new DefaultComboBoxModel<>();
       
       
       if (withReport == true) {
           for (String eachResult : bloodTestResult) {
               comboModel.addElement(eachResult);
           }
           lstMRBloodTest.setModel(comboModel);
           lblBloodTestReport.setText("Blood Test Report :");
       }
       else {
           lstMRBloodTest.setModel(comboModel);
           lblBloodTestReport.setText("Blood Test Report : (No Record)");
       }
       
       
       
        
        
        
        
    }
