    private void btnAddReportActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnAddReportActionPerformed
        boolean numberVerify = false;
        String consultanceFee = txtConsultanceFee.getText();
        
        
        boolean consultanceFeeValid = Validation.price(consultanceFee);
        
        
        if (consultanceFeeValid == false) {
            JOptionPane.showMessageDialog(this, "Consultance fee is required and must contain numbers only!", "warning", JOptionPane.WARNING_MESSAGE);
            txtConsultanceFee.setText("");
        }
        
        else {
            numberVerify = true;
        }
        
        if (numberVerify) {
            findPatientPanel.setVisible(false);
            DiseaseDescriptionPanel.setVisible(false);
            AddBloodTestReportPanel.setVisible(true);
            
            txtGlucose.setText("");
            txtCholesterol.setText("");
            txtHemoglobin.setText("");
        }
    }//GEN-LAST:event_btnAddReportActionPerformed

