    public void refreshCommonRecordPage() {
        ArrayList<String[]> patientData = File_Control.readFile("patientData.txt",true);
        ArrayList<String[]> childData = File_Control.readFile("childData.txt",true);
        
        String patientName = "";
        String patientIC = "";
        String patientGender = "";
        String patientBloodType = "";
        String patientAge = "";
        String patientRegion = "";
        String parentName ="";
        String patientContactNumber = "";
        String patientEmail = "";
        String patientRace = "";
        String allergies = "";
        String parentID = "";
        
        List<String> lifeStyle = new ArrayList<>();
        
        String patientID = patientRecordSelectedID();
        
        if (patientID.startsWith("P")) {
            for (String[] line : patientData) {
                if (line[0].equals(patientID)) {
                    patientName = line[1];
                    patientIC = line[2];
                    patientGender = line[4];
                    patientAge = line[3];
                    patientBloodType = line[9];
                    patientRegion = line[8];
                    patientContactNumber = line[6];
                    patientEmail = line[7];
                    patientRace = line[5];
                    allergies = line[10];
                    lifeStyle = Arrays.asList(line[11].split(","));
                }
            }
        }
        else {
            for (String[] line : childData) {
                if (line[0].equals(patientID)) {
                    parentID = line[1];
                    patientName = line[2];
                    patientIC = line[3];
                    patientGender = line[4];
                    patientAge = line[6];
                    patientAge = childAgeConverter(patientAge);
                    patientBloodType = line[7];
                    patientRegion = line[5];
                    patientContactNumber = "-";
                    patientEmail = "-";
                    allergies = line[8];
                    lifeStyle = Arrays.asList(line[9].split(","));
                }
            }
            
            for (String[] list : patientData) {
                if (parentID.equals(list[0])) {
                    parentName = list[1];
                    patientRace = list[5];
                }
            }
        }
        DefaultListModel<String> listModel = new DefaultListModel();
        
        if (!allergies.equals("-")) {
            String[] allergiesList = allergies.split(",");
            for (String eachAllergies : allergiesList) {
                listModel.addElement(eachAllergies);
            }
        }
        else {
            listModel.addElement("None");
        }
        
        lstPatientAllergies.setModel(listModel);
        
        String smookingBehaviour = lifeStyle.get(0);
        String drinkingBehaviour = lifeStyle.get(1);
        String exerciseBehaviour = lifeStyle.get(2);
        String eatingBehaviour = lifeStyle.get(3);
        
        lblPatientNameRCD.setText(patientName);
        lblPatientAgeRCD.setText(patientAge);
        lblPatientICRCD.setText(patientIC);
        lblPatientGenderRCD.setText(patientGender);
        lblPatientBloodRCD.setText(patientBloodType);
        lblPatientRegionRCD.setText(patientRegion);
        lblPatientContactNumberRCD.setText(patientContactNumber);
        lblEmailRCD.setText(patientEmail);
        lblPatientRaceRCD.setText(patientRace);
        lblPatientIDRCD.setText(patientID);
        
        lblPatientSmooking.setText(smookingBehaviour);
        lblPatientDrinking.setText(drinkingBehaviour);
        lblPatientExercise.setText(exerciseBehaviour);
        lblPatientEating.setText(eatingBehaviour);
        lblDiseaseHistory.setText(patientName + "'s Disease History");
        
        if (patientID.startsWith("C")) {
            lblPatientParentRCD.setText(parentName);
        }
        else {
            lblPatientParentRCD.setText("Not available");
        }
    }
