    private void btnAddAllergyActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnAddAllergyActionPerformed
        ArrayList<String[]> patientData = File_Control.readFile("patientData.txt", false);
        ArrayList<String[]> childData = File_Control.readFile("childData.txt", false);
        String allergy = "";
        String allergyLevel = "";
        
        String patientID = patientRecordSelectedID();
        
        if (cboAllerySelection.getSelectedIndex() != -1 && cboAllergiesSeverity.getSelectedIndex() != -1) {
            allergy = cboAllerySelection.getSelectedItem().toString();
            allergyLevel = cboAllergiesSeverity.getSelectedItem().toString();
            
//            DefaultListModel<String> listModel = (DefaultListModel<String>) lblExistingAllergies.getModel();
//            ArrayList<String> allAllergics = new ArrayList<>();
//            for (int i = 0 ; i < listModel.size() ; i++) {
//                allAllergics.add(listModel.get(i));
//            }
            
            
            if (patientID.startsWith("P")) {
                for (String[] line : patientData) {
                    if (line[0].equals(patientID)) {
                        if (line[10].equals("-")) {
                        line[10] = allergy + "(" + allergyLevel + ")";
                        }
                        else {
                            line[10] = line[10] + "," + allergy + "(" + allergyLevel + ")";
                        }
                    }
                }
                File_Control.writeFile("patientData.txt", patientData);

            }
            else {
                 for (String[] line : childData) {
                    if (line[0].equals(patientID)) {
                        System.out.println(line[8]);
                        if (line[8].equals("-")) {
                            line[8] = allergy + "(" + allergyLevel + ")";
                        }
                        else {
                            line[8] = line[8] + "," + allergy + "(" + allergyLevel + ")";
                        }
                    }
                }
                 File_Control.writeFile("childData.txt", childData);

            }
            refreshModifyAdditionalPage();
        }
        else {
            JOptionPane.showMessageDialog(this, "Please do not add empty allergy into system", "Warning", JOptionPane.WARNING_MESSAGE);
        }
        
    }//GEN-LAST:event_btnAddAllergyActionPerformed

