    private void cboLifeStyleSelectActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_cboLifeStyleSelectActionPerformed
        String selectedLifeStyle = cboLifeStyleSelect.getSelectedItem().toString();
        DefaultComboBoxModel comboBoxModel = new DefaultComboBoxModel();
        switch (selectedLifeStyle) {
            case "Smooking" -> {
                comboBoxModel.addElement("Never Smoked");
                comboBoxModel.addElement("Former Smoker");
                comboBoxModel.addElement("Current Smoker (Occasional)");
                comboBoxModel.addElement("Current Smoker (Daily)");
            }
            case "Drinking" -> {
                 comboBoxModel.addElement("Never Drinks");
                 comboBoxModel.addElement("Occasional Drinker");
                 comboBoxModel.addElement("Regular Drinker");
                 comboBoxModel.addElement("Heavy Drinker");
            }
            case "Exercise" -> {
                comboBoxModel.addElement("No Exercise");
                comboBoxModel.addElement("Occasional Exercise");
                comboBoxModel.addElement("Regular Exercise");
                comboBoxModel.addElement("Intensive Exercise");                
            }
            case "Eating" -> {
                comboBoxModel.addElement("Balanced Diet");
                comboBoxModel.addElement("High Fat / Sugar Diet");
                comboBoxModel.addElement("Irregular Meals");
                comboBoxModel.addElement("Vegetarian");
                comboBoxModel.addElement("Fast Food");
            }
        }
        cboLifeStyleStatusSelect.setModel(comboBoxModel);
    }//GEN-LAST:event_cboLifeStyleSelectActionPerformed

