    private void btnUpdateLifeStyleActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnUpdateLifeStyleActionPerformed
        ArrayList<String[]> patientData = File_Control.readFile("patientData.txt", false);
        ArrayList<String[]> childData = File_Control.readFile("childData.txt", false);
        
        String patientID = patientRecordSelectedID();
        if (cboLifeStyleStatusSelect.getSelectedIndex() != -1) {
            int lifeStyleSelection = cboLifeStyleSelect.getSelectedIndex();
            String lifeStyleStatus = cboLifeStyleStatusSelect.getSelectedItem().toString().strip();

            
            if (patientID.startsWith("P")) {
                for (String[] line : patientData) {
                    if (patientID.equals(line[0])) {
                    String[] lifeStyleList = line[11].split(",");
                    lifeStyleList[lifeStyleSelection] = lifeStyleStatus;
                    
                    line[11] = String.join(",", lifeStyleList);
                    }                   
                }
                File_Control.writeFile("patientData.txt", patientData);
            }
            else {
                for (String[] line : childData) {
                    if (patientID.equals(line[0])) {
                    String[] lifeStyleList = line[9].split(",");
                    lifeStyleList[lifeStyleSelection] = lifeStyleStatus;
                    
                    line[9] = String.join(",", lifeStyleList);
                    }                   
                }
                File_Control.writeFile("childData.txt", childData);
            }
            refreshModifyAdditionalPage();
        }
        else{
            JOptionPane.showMessageDialog(this, "Please select Lifestyle Status before updating data", "warning", JOptionPane.WARNING_MESSAGE);

        }
    }//GEN-LAST:event_btnUpdateLifeStyleActionPerformed

