    private void lblApprovedAppointmentMouseClicked(java.awt.event.MouseEvent evt) {//GEN-FIRST:event_lblApprovedAppointmentMouseClicked
        ArrayList<String[]> appointmentData = File_Control.readFile("appointmentData.txt", true);
        ArrayList<String[]> patientData = File_Control.readFile("patientData.txt", true);
        ArrayList<String[]> childData = File_Control.readFile("childData.txt", true);
        
        boolean nextStatus = false;
        
        Appointment appointment = new Appointment();
        appointment.setDoctorID(doctor.getUserID());
        ArrayList<String[]> tableData = appointment.getDoctorApprovedAppointment(appointmentData, patientData, childData);
        
        if (!tableData.isEmpty()) {
            nextStatus = true;
        }
        
        if (nextStatus) {
            LocalDate date = LocalDate.now();
            DayOfWeek dow = date.getDayOfWeek();

            DateTimeFormatter dateFormatter = DateTimeFormatter.ofPattern("yyyy-MM-dd");
            
            // create table model
            DefaultTableModel tableModel = new DefaultTableModel();

            String dateString = date.format(dateFormatter);
        
            // set table title
            String[] tableTitle = {"AppointmentID", "Patient Name", "Date", "Day", "Time"};
            tableModel.setColumnIdentifiers(tableTitle);

           for (String[] each : tableData) {
               tableModel.addRow(each);
           } 
           
           String appointmentTimes = Integer.toString(appointment.getTodayAppointment(appointmentData, date));
           
           
           tblApprovedAppointment.setModel(tableModel);
           tblApprovedAppointment.setEnabled(false);
           
           lblNumberOfAppointment.setText(appointmentTimes);
           lblAppointmentDate.setText(dateString);
           lblAppointmentDay.setText(dow.toString());
           
           
           PendingAppointmentPanel.setVisible(false);
           ExistingAppointmentPanel.setVisible(true);
           CheckAppointmentPanel.setVisible(false);
        }
        else {
            JOptionPane.showMessageDialog(this, "You don’t have any approved appointments yet. Please go to approve!");
        }
    }//GEN-LAST:event_lblApprovedAppointmentMouseClicked

