    private void btnGenerateMedicalReportActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnGenerateMedicalReportActionPerformed
        DefaultTableModel tableModel = (DefaultTableModel) tblMedicalReportOverview.getModel();
        
        String selectedClass = cboReportCategory.getSelectedItem().toString();
        int classIndex = 0;
        
        String selectedDetails = cboDetailsClass.getSelectedItem().toString();        
        
        switch (selectedClass) {
            case "Disease" -> { 
                classIndex = 5;
            }
            case "Gender" -> {
                classIndex = 3;
            }
            case "Region" -> {
                classIndex = 2;
            }
            case "Payment Status" -> {
                classIndex = 10;
            }
        }
        
        DefaultTableModel newTableModel = new DefaultTableModel();
        
        String[] newTableModelTitle = {"MedicalReportID","Patient Name","Region","Gender","Age","Disease","Description","Consultant Doctor","Date","Consultance Fee","Payment Status","Blood Test"};
        newTableModel.setColumnIdentifiers(newTableModelTitle);
        
        for (int i = (tableModel.getRowCount() - 1); i >= 0 ; i--) {
            if (tableModel.getValueAt(i, classIndex).equals(selectedDetails)) {
                String[] rowData = new String[tableModel.getColumnCount()];
                for (int column = 0 ; column < tableModel.getColumnCount() ; column++) {
                    rowData[column] = tableModel.getValueAt(i, column).toString();
                }
                
                newTableModel.addRow(rowData);
            }
        }
        
        showReport(newTableModel, selectedClass, selectedDetails);
        
        
    }//GEN-LAST:event_btnGenerateMedicalReportActionPerformed
    public void showReport(DefaultTableModel tableModel,String selectedClass, String selectedDetails) {
        JTable table = new JTable(tableModel);
        
        table.setEnabled(false);
        JScrollPane scrollPane = new JScrollPane(table);
        
        JDialog dialog = new JDialog();
        dialog.setTitle("Medical Report Fileted by "  + selectedClass + " ("+ selectedDetails + ")");
        dialog.setSize(1500, 400);
        dialog.add(scrollPane);
        dialog.setModal(true);
        
        dialog.setLocationRelativeTo(null);
        dialog.setVisible(true);
    }
