    private void btnChangeSafetyQuestionActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnChangeSafetyQuestionActionPerformed
        ArrayList<String[]> safetyData = File_Control.readFile("securityQuestion.txt", true);
        
        String selectedQuestion1 = cboSafetyQuestion1.getSelectedItem().toString();
        String questionAnswer1 = txtAnswerSQ1.getText().strip();
        String selectedQuestion2 = cboSafetyQuestion2.getSelectedItem().toString();
        String questionAnswer2 = txtAnswerQS2.getText().strip();
        
        String question1 = "";
        String question2 = "";
        
        for (String[] line : safetyData) {
            if(line[1].equals(selectedQuestion1)) {
                question1 = line[0];
            }
            else if (line[1].equals(selectedQuestion2)) {
                question2 = line[0];
            }
        }
        
        // validation
        // repetitive
        if (txtAnswerSQ1.isEnabled()) {
            if (selectedQuestion1.equals(selectedQuestion2)) {
                lblSafetyReminder.setText("Please don't select same question.");
            }
            else if (questionAnswer1.isEmpty() || questionAnswer2.isEmpty()) {
                lblSafetyReminder.setText("Please don't leave any fields empty");
            }
            else if (!Validation.string(questionAnswer1) || !Validation.string(questionAnswer2)) {
                lblSafetyReminder.setText("Answer can only include letters");
            }
            else {
                doctor.setSafetyQuestionID1(question1);
                doctor.setSafetyQuestionID2(question2);
                doctor.setSafetyAnswer1(questionAnswer1);
                doctor.setSafetyAnswer2(questionAnswer2);
                doctor.updateSafetyQuestion();
                lblSafetyReminder.setText("Update successfully.");

                cboSafetyQuestion1.setEnabled(false);
                txtAnswerSQ1.setEnabled(false);
                cboSafetyQuestion2.setEnabled(false);
                txtAnswerQS2.setEnabled(false);
        }
        }
        else {
            lblSafetyReminder.setText("Please edit first.");
        }
    }//GEN-LAST:event_btnChangeSafetyQuestionActionPerformed

