    public void refreshVaccination() {
        ArrayList<String[]> vaccinationData = File_Control.readFile("vaccinationData.txt", true);
        ArrayList<String[]> doctorData = File_Control.readFile("doctorData.txt", true);
        
        ArrayList<String[]> pastList = new ArrayList<>();
        ArrayList<String[]> futureList = new ArrayList<>();
        
        String patientID = cboPatientIDVaccination.getSelectedItem().toString();
        String name = lblPatientNameDisplayVaccination.getText();
        
        LocalDate date = LocalDate.now();
        
        DateTimeFormatter dateFormatter = DateTimeFormatter.ofPattern("yyyy-MM-dd");
        
        DefaultTableModel pastTableModel = new DefaultTableModel();
        DefaultTableModel upcomingTableModel = new DefaultTableModel();
        String[] tableTitle = {"VCID","Vaccination Type","Date","Description","Scheduling Doctor"};
        
        pastTableModel.setColumnIdentifiers(tableTitle);
        upcomingTableModel.setColumnIdentifiers(tableTitle);
        
        for (String[] line : vaccinationData) {
            if (line[1].equals(patientID)) {
                LocalDate vaccinationDate = LocalDate.parse(line[3], dateFormatter);
                
                if (vaccinationDate.isBefore(date)) {
                    pastList.add(line);
                }
                else if (vaccinationDate.isAfter(date) || vaccinationDate.equals(date)) {
                    // to change the date that show today
                    if (vaccinationDate.equals(date)) {
                        line[3] = line[3] + "(Today)";
                    }
                    futureList.add(line);
                }
            }
        }
        String doctor = "";
        if (!futureList.isEmpty()) {
            for (String[] list : futureList) {
                for (String[] each : doctorData) {
                    if (each[0].equals(list[6])) {
                        doctor = each[1];
                    }
                }
                String[] vaccinationDatas = {list[0],list[2],list[3], list[5], doctor};
                upcomingTableModel.addRow(vaccinationDatas);
            }
        }
        
        if (!pastList.isEmpty()) {
            for (String[] list : pastList) {
                for (String[] each : doctorData) {
                    if (each[0].equals(list[6])) {
                        doctor = each[1];
                    }
                }
                String[] vaccinationDatas = {list[0],list[2],list[3], list[5], doctor};
                pastTableModel.addRow(vaccinationDatas);
            }
        }
        
        tblVaccinationHistory.setModel(pastTableModel);
        tblUpcomingVaccination.setModel(upcomingTableModel);
        
        lblShowPatientNameVaccination.setText(name);
    }
