    private void btnShowPrescriptionDataActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnShowPrescriptionDataActionPerformed
        ArrayList<String[]> medicalData = File_Control.readFile("medicalReport.txt", true);
        ArrayList<String[]> prescriptionData = File_Control.readFile("prescriptionData.txt", true);
        curIndex = 0;
        myTempList.clear();
        
        String patientID = cboPatientID.getSelectedItem().toString().strip();
        
        String patientName = lblPatientNameRCD.getText();
        
        // use medical report id to find prescription id
        for (String[] line : medicalData) {
            if (line[1].equals(patientID)) {
                String medicalReportID = line[0];
                
                for (String[] list : prescriptionData) {
                    if (list[1].equals(medicalReportID)) {
                        myTempList.add(list);
                    }
                }
            }
        }
        
        txtPrescribingDate.setEnabled(false);
        txtPrescriptionMRID.setEnabled(false);
        txtPrescriptionID.setEnabled(false);
        
        if (!myTempList.isEmpty()) {
        IdentifyPatientRecordPanel.setVisible(false);
        ShowPatientCommonRecordPage.setVisible(false);
        ShowPatientMedicalReportPanel.setVisible(false);
        ModifyAdditionalRecordPanel.setVisible(false);
        ShowPrescriptionPanel.setVisible(true);
        
        lblPatientPrescribeData.setText(patientName + "'s Prescription Data");
        
        showPrescriptionData(curIndex);
        }
        else {
            JOptionPane.showMessageDialog(this, "“The patient does not have any prescription records yet.");
        }
    }//GEN-LAST:event_btnShowPrescriptionDataActionPerformed

