    private void cboPatientIDVaccinationActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_cboPatientIDVaccinationActionPerformed
        ArrayList<String[]> patientData = File_Control.readFile("patientData.txt", true);
        ArrayList<String[]> childData = File_Control.readFile("childData.txt", true);
        
        String patientID = cboPatientIDVaccination.getSelectedItem().toString();
        
        String name = "";
        String age = "";
        String bloodType = "";
        String region = "";
        
        if (patientID.startsWith("P")) {
            for (String[] line : patientData) {
                if (line[0].equals(patientID)) {
                    name = line[1];
                    age = line[3];
                    bloodType = line[9];
                    region = line[8];
                    break;
                }
            }
        }
        else {
            for (String[] line : childData) {
                if (line[0].equals(patientID)) {
                    name = line[2];
                    age = childAgeConverter(line[6]);
                    bloodType = line[7];
                    region = line[5];
                    break;
                }
            }
        }
        
        lblPatientNameDisplayVaccination.setText(name);
        lblPatientAgeDisplayVaccination.setText(age);
        lblPatientBloodDisplayVaccination.setText(bloodType);
        lblPatientRegionDisplayVaccination.setText(region);
        
        PatientCardVaccinationPanel.setVisible(true);
        
        btnSearchPatientVaccinationInformation.setEnabled(true);
    }//GEN-LAST:event_cboPatientIDVaccinationActionPerformed

    private void btnAddNEwVaccinationActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnAddNEwVaccinationActionPerformed
        String patientClass = cboPatientClass.getSelectedItem().toString();
        
        String patientName = lblPatientNameDisplayVaccination.getText();
        String patientAge = lblPatientAgeDisplayVaccination.getText();
        
        DefaultComboBoxModel comboModel = new DefaultComboBoxModel();
        
        if (patientClass.equals("Patient")) {
            comboModel.addElement("Influenza");
            comboModel.addElement("Tdap / Td");
            comboModel.addElement("Cervarix");
            comboModel.addElement("Gardasil4");
            comboModel.addElement("Gardasil9");
        }
        else {
            comboModel.addElement("MMR");
            comboModel.addElement("Poliomyelitis");
            comboModel.addElement("HepatitisB");
            comboModel.addElement("Influenza");
            comboModel.addElement("Tdap/Td");
        }
        
        
        cboVaccineType.setModel(comboModel);
        
        // create date model
        SpinnerDateModel model = new SpinnerDateModel(new Date(), null, null, Calendar.DAY_OF_MONTH);
        spnVaccineDate.setModel(model);
        
        
        // set date format
        JSpinner.DateEditor editor = new JSpinner.DateEditor(spnVaccineDate, "yyyy-MM-dd");
        spnVaccineDate.setEditor(editor); 
        
        spnVaccineDate.setEnabled(false);
        txtVaccinationDescription.setEnabled(false);
        btnAddVaccination.setEnabled(false);
        
        lblPatientNameVaccination.setText(patientName);
        lblPatientAgeVaccination.setText(patientAge);
        
        IdentifyPatientVaccinePanel.setVisible(false);
        VaccinationRecord.setVisible(false);
        AddNewVaccinationPanel.setVisible(true);
        
    }//GEN-LAST:event_btnAddNEwVaccinationActionPerformed

    private void cboVaccineTypeActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_cboVaccineTypeActionPerformed
        ArrayList<String[]> inventoryData = File_Control.readFile("inventoryData.txt", true);
        
        String vaccineName = cboVaccineType.getSelectedItem().toString();
        
        
        for (String[] list : inventoryData) {
            if (list[1].equals(vaccineName)) {
            String quantity = list[6];
            int amount = Integer.parseInt(quantity);
            if (amount >= 1) {
                spnVaccineDate.setEnabled(true);
                txtVaccinationDescription.setEnabled(true);
                btnAddVaccination.setEnabled(true);
            }
            else {
                spnVaccineDate.setEnabled(false);
                txtVaccinationDescription.setEnabled(false);
                btnAddVaccination.setEnabled(false);
                JOptionPane.showMessageDialog(this, "The vaccine is out of stock", "Warning", JOptionPane.WARNING_MESSAGE);
            }
        }
        }
        
        
    }//GEN-LAST:event_cboVaccineTypeActionPerformed

    private void btnAddVaccinationActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnAddVaccinationActionPerformed
        ArrayList<String[]> inventoryData = File_Control.readFile("inventoryData.txt", false);
        
        LocalDate date = LocalDate.now();
        
        String patientID = cboPatientIDVaccination.getSelectedItem().toString();
        String description = txtVaccinationDescription.getText().strip();
        String vaccineType = cboVaccineType.getSelectedItem().toString();
        String price = "";
        
        // get the selected date from JSpinner
        Date selectedDate = (Date) spnVaccineDate.getValue();
        
        //  to convert the time zone from UTC (default from JSpinner) into current time zone, and convert into localDate fromat
        LocalDate addedVaccinationDate = selectedDate.toInstant().atZone(ZoneId.systemDefault()).toLocalDate();
        
        if (!addedVaccinationDate.isAfter(date)) {
            JOptionPane.showMessageDialog(this, "Please select a date after today.", "Warning", JOptionPane.WARNING_MESSAGE);
        }
        else if (description.equals("")) {
            JOptionPane.showMessageDialog(this, "The Description field must be filled.", "Warning", JOptionPane.WARNING_MESSAGE);
        }
        else {
            // generate VCID
            String VCID = Utility_Methods.autoGenerateID("vaccinationData.txt", "VC");
            
            // convert vaccination date
            DateTimeFormatter dateFormatter = DateTimeFormatter.ofPattern("yyyy-MM-dd");
            String dateFormatted = addedVaccinationDate.format(dateFormatter);
            
            for (String[] list : inventoryData) {
                if (list[1].equals(vaccineType)) {
                    price = list[4];
                    
                    // Deduct one from the stock.
                    int stock = Integer.parseInt(list[6]);
                    stock -= 1;
                    list[6] = Integer.toString(stock);
                    
                    
                    break;
                }
            }
            
            
            String newRecord = String.join(";", VCID, patientID, vaccineType, dateFormatted, price, description , doctor.getUserID(), "1", "1");
            
            
            File_Control.addData("vaccinationData.txt", newRecord);
            
            File_Control.writeFile("InventoryData.txt", inventoryData);
            
            JOptionPane.showMessageDialog(this, "Vaccination has been successfully scheduled.");
            
            IdentifyPatientVaccinePanel.setVisible(false);
            VaccinationRecord.setVisible(true);
            AddNewVaccinationPanel.setVisible(false);
            
            txtVaccinationDescription.setText("");
            
            refreshVaccination();
            }
       
        
    }//GEN-LAST:event_btnAddVaccinationActionPerformed

