    public void showPrescriptionData(int curIndex){
        
        String Date = myTempList.get(curIndex)[3];
        String MRID = myTempList.get(curIndex)[1];
        String prescriptionID = myTempList.get(curIndex)[0];
        
        String[] prescriptionDetails = myTempList.get(curIndex)[2].split("/");
        
        String[] tableTitle = {"ItemID", "Medicine Name", "Quantity", "Frequency", "Timing"};
        
        DefaultTableModel tableModel = new DefaultTableModel();
        
        tableModel.setColumnIdentifiers(tableTitle);
        
        for (String line : prescriptionDetails) {
            String[] eachPrescription = line.split(",");
            tableModel.addRow(eachPrescription);
        }
        
        tblPrescriptionDetails.setModel(tableModel);
        
        txtPrescribingDate.setText(Date);
        txtPrescriptionMRID.setText(MRID);
        txtPrescriptionID.setText(prescriptionID);
        
        lblPageNumber.setText((curIndex+1) + " / " + myTempList.size());
        
    }
    public void modifyAppointment(String action) {
        String appointmentID = lblAppointmentID.getText().strip();
        Appointment appointment = new Appointment();
        appointment.setAppointmentID(appointmentID);
        
        appointment.doctorModifyAppointment(action);
        
        
        initializeAppointmentPending();
    }
    public void ViewPendingAppointment(int ApptIndex) {
        ArrayList<String[]> appointmentData = File_Control.readFile("appointmentData.txt",true);
        ArrayList<String[]> medicalReportData = File_Control.readFile("medicalReport.txt",true);
        ArrayList<String[]> patientList = File_Control.readFile("patientData.txt", true);
        ArrayList<String[]> childList = File_Control.readFile("childData.txt", true);
        
        String patientID = "";
        String patientName = "";
        String date = "";
        String time = "";
        String appointmentID = "";
        
        LocalDateTime appointmentDateTime = null;
        LocalDateTime loopDateTime = null;
        boolean busyStatus = false;
        
        DateTimeFormatter formatter = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm");
        
        //find appointment data
        appointmentID = myTempList.get(ApptIndex)[0];
        patientID = myTempList.get(ApptIndex)[1];
        date = myTempList.get(ApptIndex)[3];
        time = myTempList.get(ApptIndex)[5];
        String tempAppointmentDay = myTempList.get(ApptIndex)[4];
        
        if (time.charAt(1) == ':') {
            time = "0" + time;
        }
        String dateTime = date + " " + time;
        appointmentDateTime = LocalDateTime.parse(dateTime, formatter);
        
        if (patientID.startsWith("P")) {
            for (String[] line : patientList) {
            if (patientID.equals(line[0])) {
              patientName = line[1];  
            }
        }
        }
        else {
            for (String[] line : childList) {
                if (patientID.equals(line[0])) {
                    patientName = line[2];
                }
            }
        }
        
        // to show total times the patient see doctor before
        int counter =0;
        for (String[] x : medicalReportData) {
            if (patientID.equals(x[1]) && doctor.getUserID().equals(x[7])) {
                counter++;
            }
        }
        
        for (String[] each : appointmentData) {
            
            String date1 = each[3];
            String time1 = each[5];
            if (time1.charAt(1) == ':') {
            time1 = "0" + time1;
            }
            String dateTime1 = date1 + " " + time1;
            loopDateTime = LocalDateTime.parse(dateTime1, formatter);
            if (doctor.getUserID().equals(each[2]) && loopDateTime.equals(appointmentDateTime) && each[6].equals("Accepted")) {
                busyStatus = true;
                break;
            }
        }
        
         if (busyStatus) {
             txtStatus.setText("Busy");
        }
        else {
            txtStatus.setText("Free");
        }
         
        txtPatientIDAPP.setText(patientID);
        txtPatientNameAPP.setText(patientName);
        txtVisitTimeAPP.setText(Integer.toString(counter));
        lblappDate.setText(date);
        lblappTime.setText(time);
        lblappDay.setText(tempAppointmentDay);
        lblApptIndex.setText("Page" + (curIndex + 1) + " / " + (myTempList.size()));
        lblAppointmentID.setText(appointmentID);
        
        
        txtPatientIDAPP.setEnabled(false);
        txtPatientNameAPP.setEnabled(false);
        txtVisitTimeAPP.setEnabled(false);
        
    }
        
